CREATE TABLE app_payload_uploads(hash TEXT PRIMARY KEY REFERENCES app_payload_objects(hash) ON DELETE CASCADE,bytes INTEGER NOT NULL CHECK(bytes BETWEEN 0 AND 4000000),encoded_hash TEXT NOT NULL CHECK(length(encoded_hash)=64),block_bytes INTEGER NOT NULL CHECK(block_bytes IN(4096,8192,16384,32768,65536)),offset INTEGER NOT NULL DEFAULT 0 CHECK(offset BETWEEN 0 AND bytes),done INTEGER NOT NULL DEFAULT 0 CHECK(done IN(0,1) AND (done=0 OR offset=bytes)));
CREATE TABLE app_payload_upload_parts(hash TEXT NOT NULL REFERENCES app_payload_uploads(hash) ON DELETE CASCADE,offset INTEGER NOT NULL CHECK(offset>=0),bytes INTEGER NOT NULL CHECK(bytes BETWEEN 1 AND 65536),part_hash TEXT NOT NULL CHECK(length(part_hash)=64),PRIMARY KEY(hash,offset)) WITHOUT ROWID;
CREATE TRIGGER app_payload_append_only BEFORE UPDATE ON app_payload_chunks WHEN EXISTS(SELECT 1 FROM app_payload_uploads WHERE hash=OLD.hash) AND (NEW.hash<>OLD.hash OR NEW.ordinal<>OLD.ordinal OR NEW.body<>OLD.body OR EXISTS(SELECT 1 FROM app_payload_objects WHERE hash=OLD.hash AND complete=1) OR substr(NEW.data,1,length(OLD.data)) IS NOT OLD.data OR length(NEW.data)<=length(OLD.data) OR length(NEW.data)>48000) BEGIN SELECT RAISE(ABORT,'Immutable upload chunk'); END;
CREATE TRIGGER app_payload_no_chunk_delete BEFORE DELETE ON app_payload_chunks WHEN EXISTS(SELECT 1 FROM app_payload_uploads WHERE hash=OLD.hash) AND NOT EXISTS(SELECT 1 FROM app_storage_epoch WHERE id=1 AND locked=1) BEGIN SELECT RAISE(ABORT,'Upload deletion requires maintenance'); END;
CREATE TRIGGER app_payload_receipt_immutable BEFORE UPDATE ON app_payload_upload_parts BEGIN SELECT RAISE(ABORT,'Immutable upload receipt'); END;
CREATE TRIGGER app_payload_manifest_identity BEFORE UPDATE ON app_payload_uploads WHEN NEW.hash<>OLD.hash OR NEW.bytes<>OLD.bytes OR NEW.encoded_hash<>OLD.encoded_hash OR NEW.block_bytes<>OLD.block_bytes OR NEW.offset<OLD.offset OR NEW.done<OLD.done BEGIN SELECT RAISE(ABORT,'Immutable upload identity'); END;
CREATE TRIGGER app_payload_complete_guard BEFORE UPDATE OF complete ON app_payload_objects WHEN EXISTS(SELECT 1 FROM app_payload_uploads WHERE hash=OLD.hash) AND (NEW.complete<OLD.complete OR NEW.bytes<>OLD.bytes OR NEW.chunks<>OLD.chunks OR NEW.inline_data IS NOT NULL OR (NEW.complete=1 AND (NOT EXISTS(SELECT 1 FROM app_payload_uploads WHERE hash=OLD.hash AND offset=bytes) OR (SELECT count(*) FROM app_payload_chunks WHERE hash=OLD.hash)<>OLD.chunks OR (SELECT coalesce(sum(length(data)),0) FROM app_payload_chunks WHERE hash=OLD.hash)<>OLD.bytes))) BEGIN SELECT RAISE(ABORT,'Incomplete upload'); END;
CREATE TRIGGER app_payload_no_completed_insert BEFORE INSERT ON app_payload_chunks WHEN EXISTS(SELECT 1 FROM app_payload_uploads u JOIN app_payload_objects o ON o.hash=u.hash WHERE u.hash=NEW.hash AND o.complete=1) BEGIN SELECT RAISE(ABORT,'Completed upload is immutable'); END;
